/// Solve returns "NO\n" iff the grid is disconnected according to the
/// four-corner arrows rule, otherwise it returns "YES\n".
#[requires(n > 0)]
#[requires(m > 0)]
#[requires(horizontal.len() == n as usize)]
#[requires(vertical.len() == m as usize)]
// all horizontal arrows must be '<' or '>'
#[requires(forall(|i: usize| i < horizontal.len() ==>
    horizontal[i] == '<' || horizontal[i] == '>'))]
// all vertical arrows must be '^' or 'v'
#[requires(forall(|j: usize| j < vertical.len() ==>
    vertical[j] == '^' || vertical[j] == 'v'))]
#[ensures(result == vec!['N','O','\n'] <==> check_disconnected(n, m, horizontal, vertical))]
#[ensures(result == vec!['Y','E','S','\n'] <==> !check_disconnected(n, m, horizontal, vertical))]
fn solve(n: i8, m: i8, horizontal: Vec<char>, vertical: Vec<char>) -> Vec<char> {
    if check_disconnected(n, m, &horizontal, &vertical) {
        vec!['N', 'O', '\n']
    } else {
        vec!['Y', 'E', 'S', '\n']
    }
}

/// check_disconnected returns true exactly when one of the four
/// “disconnect” corner‐arrow conditions holds.
#[pure]  // mark as a pure specification‐checking function
#[requires(n > 0)]
#[requires(m > 0)]
#[requires(horizontal.len() == n as usize)]
#[requires(vertical.len() == m as usize)]
#[requires(forall(|i: usize| i < horizontal.len() ==>
    horizontal[i] == '<' || horizontal[i] == '>'))]
#[requires(forall(|j: usize| j < vertical.len() ==>
    vertical[j] == '^' || vertical[j] == 'v'))]
#[ensures(ret == (
    // top-left corner: '>' on top and 'v' on left
    (horizontal[0] == '>' && vertical[0] == 'v')
    // bottom-left corner: '<' on top and 'v' on right
    || (horizontal[0] == '<' && vertical[m as usize - 1] == 'v')
    // top-right corner: '>' on bottom and '^' on left
    || (horizontal[n as usize - 1] == '>' && vertical[0] == '^')
    // bottom-right corner: '<' on bottom and '^' on right
    || (horizontal[n as usize - 1] == '<' && vertical[m as usize - 1] == '^')
))]
fn check_disconnected(n: i8, m: i8, horizontal: &Vec<char>, vertical: &Vec<char>) -> bool {
    // Convert to usize for indexing
    let n_usize = n as usize;
    let m_usize = m as usize;

    // Corner arrows
    let h_first = horizontal[0];
    let h_last  = horizontal[n_usize - 1];
    let v_first = vertical[0];
    let v_last  = vertical[m_usize - 1];

    // Check the four disconnect conditions
    (h_first == '>' && v_first == 'v') ||
    (h_first == '<' && v_last  == 'v') ||
    (h_last  == '>' && v_first == '^') ||
    (h_last  == '<' && v_last  == '^')
}

